-- The schema TestDumpRestores syncs, dumps and restores on the pinned Oracle.
-- Every object here is one the catalog restores; the gaps own their own schemas
-- in TestDumpGaps so one gap's objects never reach another's restore.

CREATE SEQUENCE PLAIN_SEQ;

CREATE TABLE TYPES (
  ID NUMBER(10) NOT NULL,
  AMOUNT NUMBER(12, 2) DEFAULT 0 NOT NULL,
  SCALED NUMBER(*, 2),
  LABEL VARCHAR2(50 CHAR) DEFAULT 'x' NOT NULL,
  NATIONAL NVARCHAR2(20),
  NOTE CLOB,
  RAW_DATA RAW(16),
  CREATED DATE DEFAULT SYSDATE,
  AT TIMESTAMP(3),
  "Mixed Case" NUMBER,
  CONSTRAINT TYPES_PK PRIMARY KEY (ID),
  CONSTRAINT TYPES_LABEL_UK UNIQUE (LABEL),
  CONSTRAINT TYPES_AMOUNT_CK CHECK (AMOUNT >= 0)
);

COMMENT ON TABLE TYPES IS 'types the dump reads';
COMMENT ON COLUMN TYPES.NOTE IS 'a note';
COMMENT ON COLUMN TYPES."Mixed Case" IS 'a quoted column';

CREATE TABLE IDENT (
  ID NUMBER GENERATED ALWAYS AS IDENTITY (START WITH 5 INCREMENT BY 2),
  COMPUTED AS (ID * 2),
  HIDDEN NUMBER INVISIBLE DEFAULT 7,
  CONSTRAINT IDENT_PK PRIMARY KEY (ID)
);

CREATE TABLE PARENT (
  ID NUMBER NOT NULL,
  NAME VARCHAR2(40) NOT NULL,
  CONSTRAINT PARENT_PK PRIMARY KEY (ID),
  CONSTRAINT PARENT_NAME_UK UNIQUE (NAME)
);

CREATE TABLE CHILD (
  ID NUMBER NOT NULL,
  PARENT_ID NUMBER NOT NULL,
  QTY NUMBER DEFAULT 1,
  CONSTRAINT CHILD_PK PRIMARY KEY (ID),
  CONSTRAINT CHILD_FK FOREIGN KEY (PARENT_ID) REFERENCES PARENT (ID) ON DELETE CASCADE,
  CONSTRAINT CHILD_QTY_CK CHECK (QTY > 0)
);

CREATE INDEX CHILD_PARENT_IDX ON CHILD (PARENT_ID);
CREATE INDEX CHILD_PARENT_DESC_IDX ON CHILD (PARENT_ID DESC) INVISIBLE;
CREATE UNIQUE INDEX PARENT_UPPER_NAME_IDX ON PARENT (UPPER(NAME));

CREATE VIEW PARENT_VIEW AS SELECT ID, NAME FROM PARENT;
COMMENT ON TABLE PARENT_VIEW IS 'a view comment';
CREATE TRIGGER PARENT_VIEW_INSERT_TRG INSTEAD OF INSERT ON PARENT_VIEW
BEGIN
  INSERT INTO PARENT (ID, NAME) VALUES (:NEW.ID, :NEW.NAME);
END;

CREATE MATERIALIZED VIEW PARENT_MV AS SELECT ID, NAME FROM PARENT;
COMMENT ON MATERIALIZED VIEW PARENT_MV IS 'a materialized view comment';
CREATE INDEX PARENT_MV_NAME_IDX ON PARENT_MV (NAME);

CREATE TRIGGER PARENT_TRG BEFORE INSERT ON PARENT FOR EACH ROW BEGIN NULL; END;

CREATE PROCEDURE TOUCH (P_ID IN NUMBER) AS BEGIN NULL; END;
CREATE FUNCTION DOUBLE_IT (P IN NUMBER) RETURN NUMBER AS BEGIN RETURN P * 2; END;
